function testPricingModule() {
  // Test case 1: Zero price
  assert.equal(calculatePrice(0, 0.1), 0);

  // Test case 2: Negative price
  assert.equal(calculatePrice(-10, 0.1), -10);

  // Test case 3: Zero discount
  assert.equal(calculatePrice(100, 0), 100);

  // Test case 4: Maximum discount
  assert.equal(calculatePrice(100, 1), 0);

  // Test case 5: Exact discount
  assert.equal(calculatePrice(100, 0.5), 50);

  // Test case 6: Decimal discount
  assert.equal(calculatePrice(100, 0.25), 75);

  // Test case 7: Large price
  assert.equal(calculatePrice(1000000, 0.1), 900000);

  // Test case 8: Small discount
  assert.equal(calculatePrice(100, 0.01), 99);

  // Test case 9: Price with decimal
  assert.equal(calculatePrice(99.99, 0.1), 89.991);

  // Test case 10: Discount with decimal
  assert.equal(calculatePrice(100, 0.15), 85);

  // Test case 11: Price and discount both zero
  assert.equal(calculatePrice(0, 0), 0);

  // Test case 12: Large discount with large price
  assert.equal(calculatePrice(50000, 0.9), 5000);
}
